import { createContext, useContext, useState, ReactNode } from 'react';

type TabsContextValue = {
  active: string;
  setActive: (id: string) => void;
};

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabsContext(): TabsContextValue {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error('Tabs subparts must be used inside <Tabs>');
  return ctx;
}

export function Tabs({ defaultActive, children }: { defaultActive: string; children: ReactNode }) {
  const [active, setActive] = useState(defaultActive);
  return <TabsContext.Provider value={{ active, setActive }}>{children}</TabsContext.Provider>;
}

export function TabList({ children }: { children: ReactNode }) {
  return <div role="tablist">{children}</div>;
}

export function TabTrigger({ id, children }: { id: string; children: ReactNode }) {
  const { active, setActive } = useTabsContext();
  return (
    <button role="tab" aria-selected={active === id} onClick={() => setActive(id)}>
      {children}
    </button>
  );
}

export function TabPanel({ id, children }: { id: string; children: ReactNode }) {
  const { active } = useTabsContext();
  if (active !== id) return null;
  return <div role="tabpanel">{children}</div>;
}
